3	// These regression cases pin the storage-integration boundary analyzed in
4	// docs/storage-boundary-analysis.md: how the service and the router treat a
5	// caller-supplied service.Store whose backend wraps the miss sentinel, returns
6	// a register status together with an error, or is paired with a nil health
7	// check. They run only against the public HTTP surface (POST/GET
8	// /v1/artifacts, GET /healthz) through NewRouterWithStore.
9	
10	import (
11		"errors"
12		"fmt"
13		"net/http"
14		"testing"
15	
16		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
17	)
18	
19	// boundaryStore is a caller-supplied service.Store written only against the
20	// exported storage contract. It keeps records in memory like the SQLite
21	// adapter and adds three backend behaviors the contract leaves to the
22	// implementation: a wrapped miss sentinel, a register status returned
23	// together with an error, and a plain backend failure.
24	type boundaryStore struct {
25		records []service.Record
26		byID    map[string]int               // repository\x00digest -> records index
27		tags    map[string]map[string]string // repository -> tag -> digest
28	
29		fault          error                  // non-nil: every method fails with it
30		missWrapper    func(error) error      // non-nil: transforms the lookup miss sentinel
31		registerStatus service.RegisterStatus // status Register returns together with fault
32	}
33	
34	func newBoundaryStore() *boundaryStore {
35		return &boundaryStore{
36			byID: make(map[string]int),
37			tags: make(map[string]map[string]string),
38		}
39	}
40	
41	func boundaryID(repository, digest string) string { return repository + "\x00" + digest }
42	
43	func (b *boundaryStore) miss(err error) error {
44		if b.missWrapper != nil {
45			return b.missWrapper(err)
46		}
47		return err
48	}
49	
50	func (b *boundaryStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
51		if b.fault != nil {
52			return service.Record{}, b.registerStatus, b.fault
53		}
54		key := boundaryID(in.Repository, in.Digest)
55		if idx, ok := b.byID[key]; ok {
56			existing := b.records[idx]
57			if existing.Tag == in.Tag &&
58				existing.SignatureVerified == in.SignatureVerified &&
59				existing.RetentionDays == in.RetentionDays &&
60				existing.SizeBytes == in.SizeBytes {
61				return existing, service.StatusDuplicate, nil
62			}
63			return service.Record{}, service.StatusConflict, nil
64		}
65		b.byID[key] = len(b.records)
66		b.records = append(b.records, in)
67		if b.tags[in.Repository] == nil {
68			b.tags[in.Repository] = make(map[string]string)
69		}
70		b.tags[in.Repository][in.Tag] = in.Digest
71		return in, service.StatusCreated, nil
72	}
73	
74	func (b *boundaryStore) ListRecords(repository string) ([]service.Record, error) {
75		if b.fault != nil {
76			return nil, b.fault
77		}
78		var out []service.Record
