		t.Run(name, func(t *testing.T) {
			body := `{"repository":"r","digest":"` + digestA + `","tag":"t",` +
				`"signature_verified":true,"retention_days":` + itoa(tc.retention) +
				`,"size_bytes":` + itoa(tc.size) + `}`
