// name: every required key spelled with a \u escape is still recognized, and
// escaped/plain spellings of the same decoded name collide as duplicates
// whose document order decides the value. Backtick strings keep the
// backslash literal, so the JSON text really carries the escapes.
func TestParseRegistrationEscapedKeyNames(t *testing.T) {
