	if err != nil {
		t.Fatalf("all-escaped keys: %v", err)
	}
	if want := wantRegisterInput("team/uni", digestA, "release", true, 30, 1); got != want {
		t.Fatalf("parsed input = %+v, want %+v", got, want)
