// keep the first-wins cases table self-describing.
func rawFor(want service.Query) string {
	switch want.Kind {
	case service.QueryByTag:
		return "repository=" + want.Repository + "&tag=" + want.Tag
	case service.QueryByDigest:
		return "repository=" + want.Repository + "&digest=" + want.Digest
	default:
		return "repository=" + want.Repository
	}
}

